# Helper functions
function parse_amount_to_cents(str,   s, sign, parts, dollars, cents) {
    # remove surrounding whitespace and quotes
    gsub(/^[[:space:]"]+|[[:space:]"]+$/, "", str)
    # remove commas
    gsub(/,/, "", str)
    sign = 1
    if (str ~ /^-/) {
        sign = -1
        str = substr(str, 2)
    }
    if (index(str, ".") > 0) {
        split(str, parts, ".")
        dollars = parts[1]
        cents = parts[2]
        # normalize cents to 2 decimals
        if (length(cents) == 0) {
            cents = "00"
        } else if (length(cents) == 1) {
            cents = cents "0"
        } else if (length(cents) == 2) {
            # keep as is
        } else {
            # e.g. 3 decimal digits: 89.990 -> 99
            # wait, could there be rounding or is it exact 0-3 decimals?
            # "Amounts may have 0-3 decimal digits (e.g. 2000, 300.1, 89.990)."
            # Let's check length: if length > 2, does it have trailing 0s or should we handle it?
            cents = substr(cents, 1, 2)
        }
    } else {
        dollars = str
        cents = "00"
    }
    if (dollars == "") dollars = "0"
    return sign * (dollars * 100 + cents)
}

function cents_to_str(c,   sign, d, rem, s) {
    if (c < 0) {
        sign = "-"
        c = -c
    } else {
        sign = ""
    }
    d = int(c / 100)
    rem = c % 100
    if (rem < 10) {
        s = sprintf("%s%d.0%d", sign, d, rem)
    } else {
        s = sprintf("%s%d.%d", sign, d, rem)
    }
    return s
}
